struct FEMenuEntry {
	char pad0[4];
	FEMenuEntry *next;
	char pad1[88];
	virtual void d0();
	virtual void d1();
	virtual void d2();
	virtual void d3();
	virtual void d4();
	virtual void d5();
	virtual void d6();
	virtual void d7();
	virtual void d8();
	virtual void d9();
	virtual void Disable(bool disabled = true);
};

struct FEMenu {
	char pad[64];
	FEMenuEntry *entries;
};

struct PauseMenuSystem {
	char pad[156];
	int pause_controller;
};

struct Game {
	char pad0[176];
	int num_players;
	int active_player;
	int player_device[102];
	int surfer_index[8];

	int get_num_active_players() const { return num_players; }
	int get_active_player() const { return active_player; }
	int get_player_device(int player) const { return player_device[player]; }
	int get_player_from_device(int device) const {
		for (int i = 0; i < num_players; ++i)
			if (player_device[i] == device)
				return i;
		return -1;
	}
	int GetSurferIdx(int player) const { return surfer_index[player]; }
};

struct SurferTrick {
	char pad[12];
	int flags;
	char tail[72];
};

struct SurferData {
	char pad[20];
	int trickBook[158];
};

struct UnlockingManager {
	bool isSurferTrickUnlocked(int trick, bool ignore_learning = false) const;
};

extern Game *g_game_ptr;
extern SurferTrick GTrickList[];
extern SurferData SurferDataArray[];
extern UnlockingManager unlockManager;
extern int SpecialFlag;
extern int TRICKBOOK_SIZE;

enum { NUM_TYPES = 4 };
#define assert(x) ((void)0)

struct TrickTypeMenuClass {
	char pad[120];
	PauseMenuSystem *sys;
	FEMenu *sub_menus[NUM_TYPES];
	int trick_list_index[NUM_TYPES][50];

	void OnActivate();
};

void TrickTypeMenuClass::OnActivate()
{
	FEMenuEntry* tmp;
	int surfer_idx = -1;

	if( g_game_ptr->get_num_active_players() == 1 )
	{
		int active_player = g_game_ptr->get_active_player();
		assert( g_game_ptr->get_player_device( active_player ) == sys->pause_controller );
		surfer_idx = g_game_ptr->GetSurferIdx( active_player );
	}
	else
	{
		int active_player = g_game_ptr->get_player_from_device( sys->pause_controller );
		assert( g_game_ptr->get_player_device( active_player ) == sys->pause_controller );
		surfer_idx = g_game_ptr->GetSurferIdx( active_player );
	}
	// Disable tricks that haven't been learned yet, or don't exist for current surfer;
	for(int j=0; j<NUM_TYPES; j++)
	{
		tmp = sub_menus[j]->entries;

		int i=0;
		while(tmp)
		{
			int index = trick_list_index[j][i];
			bool not_learned = GTrickList[index].flags & SpecialFlag && !unlockManager.isSurferTrickUnlocked(index, true);  //  Check to see if a trick is open, but only if it it not currently being learned.
			bool not_avail = true;

			for(int k=0; k<TRICKBOOK_SIZE; k++)
				if(index == SurferDataArray[surfer_idx].trickBook[k])
				{
					not_avail = false;
					break;
				}

			tmp->Disable(not_avail || not_learned);
			tmp = tmp->next;
			i++;
		}
	}
	//FEMenu::OnActivate();
}
